function insertIntoBST(root, val) {
  const fresh = new TreeNode(val);
  if (root === null) return fresh;
  let node = root;
  for (;;) {
    const side = val < node.val ? "left" : "right";
    if (node[side] === null) {
      node[side] = fresh;                                  // attach to the empty side
      return root;
    }
    node = node[side];
  }
}

