TreeNode insertIntoBST(TreeNode root, int val) {
    TreeNode fresh = new TreeNode(val);
    if (root == null) return fresh;
    TreeNode node = root;
    while (true) {
        if (val < node.val) {
            if (node.left == null) { node.left = fresh; return root; }    // attach to the empty side
            node = node.left;
        } else {
            if (node.right == null) { node.right = fresh; return root; }
            node = node.right;
        }
    }
}

